import numpy as npfrom mirrors import MirrorPrismfrom mirror_utils import transform_pointsfrom gui_utils.mouse import MouseButtons, ButtonStatesfrom layout import LAYOUTclass RectangularPrism(MirrorPrism):    def __init__(self, ):        self._n = 4        self._aspect = (1. + np.sqrt(5.)) / 2.        super(RectangularPrism, self).__init__()    @classmethod    def get_name(cls):        return " rectangle "    def get_surfaces(self):        """        Get Surface() objects (corresponding to all mirrors) from current params        """    def get_unscaled_shape(self, **kwargs):        """        Get coordinates of vertices of current shape,  fit into the unit square.        """        if self._aspect > 1:            y_span = 0.5 / self._aspect            x_span = 0.5        else:            x_span = 0.5 * self._aspect            y_span = 0.5        points = np.array([[0.5 - x_span, 0.5 - y_span],                           [0.5 - x_span, 0.5 + y_span],                           [0.5 + x_span, 0.5 + y_span],                           [0.5 + x_span, 0.5 - y_span], ])        return points    def _mouse_adjust(self, pos, d_pos, d_button, button_state, keyboard_state):        if button_state[MouseButtons.LEFT] == ButtonStates.DOWN:            if d_pos is not None:                change = d_pos[1]                if change != 0:                    self._aspect *= (1.1 ** np.sign(change))                    self._mask = None    @classmethod    def get_icon_vertices(cls):        top_y = LAYOUT['icons']['fig_top_y']        bottom_y = LAYOUT['icons']['fig_bottom_y']        text_y = LAYOUT['icons']['text_bottom_y']        area_height = bottom_y - top_y        center_y = (top_y + bottom_y) / 2        rect_height = area_height / 2        rect_width = 0.75        return {'points': [(0.5 + rect_width / 2, center_y + rect_height / 2),                           (0.5 - rect_width / 2, center_y + rect_height / 2),                           (0.5 - rect_width / 2, center_y - rect_height / 2),                           (0.5 + rect_width / 2, center_y - rect_height / 2),                           (0.5 + rect_width / 2, center_y - rect_height / 3),                           (0.5 + rect_width / 2, center_y)],                'text_center_bottom': [0.5, text_y],                'final_line_dashed': True}